import {telemetry, infer, machines, jobs, baseline, optimize, parseCSV, clamp} from './engine.js';
import {createAutoDemo} from './demo.js';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number.isFinite(v)?`$${v.toFixed(2)}`:'Unavailable', pct=v=>`${Math.round(v*100)}%`, min=v=>`${Math.round(v)} min`;
let model;try{const r=await fetch('model.json');if(!r.ok)throw Error('Model unavailable');model=await r.json();}catch(e){$('#app').innerHTML='<h1>Model could not load.</h1><p>Refresh the page to try again. For a downloaded copy, use the local server instructions in README.md.</p>';throw e;}
const state={fleet:machines(),queue:jobs(),selected:'P03',mode:Object.fromEntries(machines().map(m=>[m.id,'normal'])),severity:.8,seed:28,playing:true,view:'overview',options:{downtime:60,lateRate:12,machineRate:3},plan:null,applied:null,logs:[],imported:{},source:'Synthetic telemetry',checklist:{}};
let wasPlaying=false;
const autoDemo=createAutoDemo({model,printer,onOpen:()=>{wasPlaying=state.playing;state.playing=false;},onClose:()=>{state.playing=wasPlaying;render();}});
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function log(message,type=''){state.logs.unshift({message,type,time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})});state.logs=state.logs.slice(0,6);}
function updateTelemetry(){for(const m of state.fleet){m.rows=state.imported[m.id]||telemetry(state.mode[m.id],state.seed+Number(m.id.slice(1))*79,state.severity);m.result=infer(m.rows,model);m.concern=m.result.concern;}state.seed++;}
log('Factory connected. Six synthetic telemetry streams active.');updateTelemetry();
function current(){return state.fleet.find(m=>m.id===state.selected);}
function original(){return baseline(state.queue,state.fleet,state.options);}
function title(eyebrow,name,desc,actions=''){return `<div class="page-title"><div><span class="eyebrow">${eyebrow}</span><h1>${name}</h1><p class="subtitle">${desc}</p></div><div class="toolbar">${actions}</div></div>`;}
function notice(){return `<div class="notice"><span>◈</span><span><strong>${esc(state.source)}</strong> · Model scores describe similarity to training scenarios. Physical failure probability is unvalidated.</span><a class="text-link" href="#model">View evidence →</a></div>`;}
function printer(m){let orange=m.concern>.4, frame=orange?'#b9a48b':'#9dad92', accent=orange?'#d5905e':'#92b178',running=!m.offline;return `<svg viewBox="0 0 200 135" aria-hidden="true"><ellipse cx="102" cy="124" rx="66" ry="6" fill="#e9ecdf"/><path d="M44 32L139 21L160 35L64 47Z" fill="#e7ebdf"/><path d="M44 32v83l20 13V47M139 21v84l21 14V35" fill="none" stroke="${frame}" stroke-width="5" stroke-linejoin="round"/><path d="M64 47v81M160 35v84M44 115l95-10 21 14-96 9Z" fill="none" stroke="${frame}" stroke-width="4"/><path d="M52 53l96-10M52 58l96-10" stroke="#bcc8ae" stroke-width="2"/><path d="M93 44v20l13 4 8-2V45Z" fill="#74856d"/><path d="M107 69v9" stroke="${accent}" stroke-width="3"/><path d="M58 103l79-9 14 9-78 9Z" fill="#d4dfc8" stroke="#aebda0"/><path d="M91 95v-9l18-3 16 7v10l-18 3Z" fill="${accent}"/><path d="M91 86l17 7 17-3M108 94v9" fill="none" stroke="#ffffff60"/><path d="M145 65h11v16h-11Z" fill="#697b5e"/><path d="M147 69h7v6h-7Z" fill="${running?'#c0dba7':'#d5c9b6'}"/><circle cx="154" cy="78" r="1" fill="#dedfcc"/><circle cx="33" cy="32" r="11" fill="#849777"/><circle cx="33" cy="32" r="6" fill="#edf0e4"/><path d="M33 20v-5h12v8" stroke="#a8b899" fill="none" stroke-width="3"/>${running?'<path d="M106 77v6" stroke="'+accent+'" stroke-width="1.5" stroke-dasharray="2 2"><animate attributeName="stroke-dashoffset" from="0" to="12" dur="1.5s" repeatCount="indefinite"/></path>':''}</svg>`;}
function metrics(){const b=original(), active=state.fleet.filter(m=>!m.offline),watch=active.filter(m=>m.concern>.4);return `<div class="kpis"><div class="kpi"><div class="label">Machines available <span class="icon">◫</span></div><div class="value">${active.length}<span style="font-size:16px;color:#a7b19e"> / 6</span></div><small>${state.fleet.filter(m=>m.offline).length} excluded from new work</small></div><div class="kpi ${watch.length?'warn':''}"><div class="label">Needs attention <span class="icon">⌁</span></div><div class="value">${String(watch.length).padStart(2,'0')}</div><small>Model anomaly score above 40%</small></div><div class="kpi"><div class="label">Queued orders <span class="icon">▤</span></div><div class="value">12</div><small>${money(state.queue.reduce((s,j)=>s+j.value,0))} in order value</small></div><div class="kpi ${b.cost>20?'warn':''}"><div class="label">Scenario cost <span class="icon">↗</span></div><div class="value">${money(b.cost)}</div><small>Delay penalties + risk-weighted waste</small></div></div>`;}
function floor(){return `<section class="panel"><div class="panel-head"><div><h2>The production floor</h2><p>Select a machine to inspect its signals.</p></div><span class="chip"><i class="live-dot"></i>${state.playing?'STREAMING':'HELD'} · 6 MACHINES</span></div><div class="fleet-grid">${state.fleet.map(m=>`<button class="machine ${m.id===state.selected?'selected':''} ${m.concern>.4?'alert':''} ${m.offline?'offline':''}" data-machine="${m.id}" aria-pressed="${m.id===state.selected}"><div class="machine-top"><strong>${m.id} / ${m.name}</strong><span class="chip ${m.concern>.4?'orange':''}">${m.offline?'OFFLINE':m.concern>.4?'INSPECT':'RUNNING'}</span></div><div class="machine-name">FDM / ${m.materials.join(' + ')}</div>${printer(m)}<div class="machine-score"><span>Anomaly score</span><b>${pct(m.concern)}</b></div><div class="meter"><i style="width:${Math.max(3,m.concern*100)}%"></i></div><div class="machine-job"><span>${m.offline?'New work blocked':`Next available in ${m.available}m`}</span><span>${m.speed.toFixed(2)}×</span></div></button>`).join('')}</div><div class="floor-note"><div class="legend"><span><i></i>Normal</span><span><i class="orange"></i>Inspect</span></div><span>Current jobs stay on their machines.</span></div></section>`;}
const featureLabels={temperature_std_c:'Temperature variation',temperature_slope_c_per_sample:'Temperature trend',motor_mean_a:'Motor current',vibration_mean_mm_s:'Vibration',extrusion_mean_mm_s:'Extrusion flow',extrusion_slope_mm_s_per_sample:'Extrusion trend'};
function detail(){const m=current(),r=m.result;let rec=r.index===1?'Inspect nozzle and filament path before assigning new work. Queue changes cannot rescue a part already printing.':r.index===2?'Inspect the temperature sensor, heater, and control settings. Confirm the signal with a physical measurement.':r.index===3?'Inspect mechanical motion, fasteners, and bearings. Validate the vibration signal before maintenance.':'The observed window resembles normal training data. Keep monitoring; this does not guarantee the machine is healthy.';
return `<section class="panel detail-panel"><div class="detail-head"><div><span class="eyebrow">MACHINE INTELLIGENCE</span><h2 class="detail-title">${m.id} / ${m.name}</h2></div><span class="chip ${r.concern>.4?'orange':''}">${m.offline?'OFFLINE':r.index?'ANOMALY':'NORMAL'}</span></div><div><div class="score-large">${pct(r.concern)} <small>anomaly score</small></div><p class="detail-desc">${r.index?'Pattern: <strong>'+esc(r.label)+'</strong>':'Observed pattern: <strong>normal operation</strong>'}<br>1 − classifier normal score; not failure probability.</p><h3 style="font-size:10px">Strongest signal contributions</h3><div class="signals">${r.contributions.slice(0,3).map(f=>`<div class="signal"><div><span>${featureLabels[f.name]}</span><b>${f.deviation.toFixed(1)}σ</b></div><div class="meter"><i style="width:${clamp(f.deviation*10,2,100)}%"></i></div></div>`).join('')}</div><span class="subtle">σ = deviation from synthetic healthy baseline</span></div><div><div class="recommendation"><h3>↗ Suggested next action</h3><p>${rec}</p></div><p class="subtle" style="line-height:1.8">Risk-weighted delay assumption: ${min(r.concern*state.options.downtime)} per queued order. Assumes ${state.options.downtime} min disruption at maximum score.</p></div><div class="detail-buttons"><button class="btn primary full" data-action="optimize">Optimize production →</button><button class="btn small" data-action="offline">${m.offline?'Restore machine':'Take offline'}</button><button class="btn small" data-action="maintain">Simulate service</button></div></section>`;}
function chart(){const m=current(),rows=m.rows, w=610,h=120, y=r=>(h-18)-(r.temp_c-180)/75*(h-27),x=i=>i/(rows.length-1)*(w-30)+22,path=rows.map((r,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${clamp(y(r),4,h-12).toFixed(1)}`).join(' '),last=rows.at(-1);return `<section class="panel"><div class="panel-head"><div><h2>Signal history</h2><p>${m.id} · Temperature, latest ${rows.length} samples</p></div><span class="chip">${state.imported[m.id]?'IMPORTED CSV':'GENERATED · 10 SEC / SAMPLE'}</span></div><svg class="chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Temperature trace for ${m.id}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d99e73" stop-opacity=".18"/><stop offset="1" stop-color="#d99e73" stop-opacity="0"/></linearGradient></defs>${[190,210,230,250].map(t=>`<line x1="22" y1="${y({temp_c:t})}" x2="610" y2="${y({temp_c:t})}" stroke="#edf0e6"/><text x="0" y="${y({temp_c:t})-3}" font-size="7" fill="#a5af97">${t}°</text>`).join('')}<path d="${path} L${x(rows.length-1)},${h} L22,${h}Z" fill="url(#chart-fill)"/><path d="${path}" fill="none" stroke="#d69967" stroke-width="2"/></svg><div class="chart-labels"><span>${min((rows.at(-1).timestamp-rows[0].timestamp)/60)} window</span><span>Latest sample</span></div><div class="chart-metrics"><div>Temperature<b>${last.temp_c.toFixed(1)} °C</b></div><div>Vibration<b>${last.vibration_mm_s.toFixed(2)} mm/s</b></div><div>Motor current<b>${last.motor_a.toFixed(2)} A</b></div><div>Extrusion flow<b>${last.extrusion_mm_s.toFixed(2)} mm/s</b></div></div></section>`;}
function overview(){return title('OPERATIONS / LIVE WORKSPACE','A clearer view of your factory.','Catch abnormal signals. Understand the cost. Keep production moving.',`<button class="btn" data-action="import">↑ Import CSV</button><button class="btn ${state.playing?'':'dark'}" data-action="play">${state.playing?'Ⅱ Hold telemetry':'▶ Play telemetry'}</button>`)+notice()+metrics()+`<div class="row"><div>${floor()}${chart()}<section class="panel"><div class="panel-head"><div><h2>Stress-test a machine</h2><p>Change the data; watch the model respond.</p></div><span class="chip">SANDBOX</span></div><div class="controls"><select id="fault" aria-label="Fault to simulate"><option value="blockage">Extrusion blockage</option><option value="thermal">Thermal instability</option><option value="vibration">Mechanical vibration</option><option value="normal">Normal operation</option></select><select id="severity" aria-label="Fault severity"><option value=".8" ${state.severity===.8?'selected':''}>Strong signal</option><option value=".35" ${state.severity===.35?'selected':''}>Subtle signal</option></select><button class="btn danger" data-action="fault">Inject on ${state.selected}</button><button class="btn small" data-action="sample">Sample CSV ↓</button></div></section></div><div>${detail()}<section class="panel"><div class="panel-head"><h2>Decision log</h2><span class="subtle">THIS SESSION</span></div><ul class="activity">${state.logs.map(l=>`<li><i class="${l.type}"></i>${esc(l.message)}<small>${l.time}</small></li>`).join('')}</ul></section><section class="panel"><span class="eyebrow">NEXT STEP</span><h2 style="margin-top:10px;line-height:1.6">Turn machine signals<br>into a production plan.</h2><p style="font-size:10px">Compare schedules before you act. The optimizer handles material constraints and keeps current jobs in place.</p><a href="#schedule" class="text-link" style="font-size:11px">Open production planner →</a></section></div></div>`;}
function gantt(p){const max=Math.max(300,p.makespan||0);return `<div class="table-wrap"><div class="gantt">${state.fleet.map(m=>`<div class="gantt-row"><span>${m.id}</span><div class="gantt-track">${p.rows.filter(r=>r.machineId===m.id).map(r=>`<div class="gantt-bar ${r.delay>0?'delayed':''}" style="left:${r.start/max*100}%;width:${(r.end-r.start)/max*100}%" title="${r.id} · ${esc(r.name)} · ${min(r.start)}–${min(r.end)}">${r.id}</div>`).join('')}${m.offline?'<span style="font-size:9px;position:absolute;top:10px;left:10px;color:#9da68f">Excluded from new assignments</span>':''}</div></div>`).join('')}<div class="gantt-axis">${Array.from({length:6},(_,i)=>`<span>${Math.round(i*max/5)}m</span>`).join('')}</div></div></div>`;}
function schedule(){const b=original(),p=state.plan||b,diff=b.cost-p.cost,changed=p.rows.filter(r=>b.rows.find(j=>j.id===r.id)?.machineId!==r.machineId).length;return title('OPERATIONS / PRODUCTION PLANNER','A better plan, before you act.','Compare deadline, machine-health, and material constraints across the next 12 orders.',`<button class="btn" data-action="report">↓ Export analysis</button><button class="btn primary" data-action="optimize">${state.plan?'Recalculate plan':'Optimize production'} →</button>`)+notice()+`${state.applied?'<div class="status-banner">Plan accepted in this sandbox. No commands have been sent to physical machines.</div>':''}${p.unassigned?`<div class="status-banner warn">Cannot schedule ${p.unassigned}: no compatible machine is online. Restore a PETG-capable machine.</div>`:''}<div class="two-col"><section class="panel"><div class="panel-head"><h2>Cost of the next production cycle</h2><span class="chip">SCENARIO ESTIMATE</span></div><div class="comparison"><div class="comparison-box"><span>ROUND-ROBIN BASELINE</span><strong>${money(b.cost)}</strong><small>${Number.isFinite(b.late)?b.late:'—'} late orders</small></div><div class="comparison-arrow">→</div><div class="comparison-box after"><span>${state.plan?'PROPOSED SCHEDULE':'AWAITING OPTIMIZATION'}</span><strong>${money(p.cost)}</strong><small>${Number.isFinite(p.late)?p.late:'—'} late orders</small></div></div><p class="schedule-note">${state.plan&&Number.isFinite(diff)?`Calculated reduction: <strong>${money(diff)}</strong> (${b.cost?pct(diff/b.cost):'0%'}). ${changed} orders assigned to a different machine.`:'Run the optimizer to compute a comparison from the current telemetry.'}<br>Costs are penalties and a risk-weighted waste proxy, rather than measured profit or savings.</p></section><section class="panel"><div class="panel-head"><div><h2>Scenario assumptions</h2><p>Changing an assumption recalculates the comparison.</p></div></div><div class="form-row"><label class="form-field">Disruption at max score (min)<input type="number" min="0" max="240" step="5" id="downtime" value="${state.options.downtime}"></label><label class="form-field">Late penalty ($/hour)<input type="number" min="0" max="1000" step="1" id="lateRate" value="${state.options.lateRate}"></label><label class="form-field">Machine cost ($/hour)<input type="number" min="0" max="100" step=".5" id="machineRate" value="${state.options.machineRate}"></label></div><p class="schedule-note">Model anomaly score is used as an adjustable disruption weight. Scores are not calibrated physical probabilities.</p></section></div><section class="panel"><div class="panel-head"><div><h2>${state.plan?'Proposed dispatch schedule':'Baseline dispatch schedule'}</h2><p>${state.plan?esc(state.plan.algorithm):'Compatible round-robin assignment'} · Time measured from now</p></div><button class="btn dark" data-action="accept" ${!state.plan||!Number.isFinite(p.cost)?'disabled':''}>Accept sandbox plan</button></div>${gantt(p)}<div class="floor-note"><div class="legend"><span><i></i>On time</span><span><i class="orange"></i>Late</span></div><span>Blocks include risk-weighted interruption.</span></div></section><section class="panel"><div class="panel-head"><h2>Order-level decisions</h2><span class="subtle">ALL QUEUED ORDERS</span></div><div class="table-wrap"><table><thead><tr><th>Order / part</th><th>Material</th><th>Machine</th><th>Finish</th><th>Due</th><th>Delay</th><th>Waste proxy</th></tr></thead><tbody>${[...p.rows].sort((a,b)=>a.id.localeCompare(b.id)).map(r=>`<tr><td><strong>${r.id}</strong> / ${r.name}</td><td><span class="chip">${r.material}</span></td><td>${r.machineId}${state.plan&&b.rows.find(j=>j.id===r.id)?.machineId!==r.machineId?'<span class="chip orange" style="margin-left:5px">MOVED</span>':''}</td><td>${min(r.end)}</td><td>${min(r.due)}</td><td class="${r.delay?'late':'good'}">${r.delay?min(r.delay):'On time'}</td><td>${money(r.riskCost)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function modelView(){const e=model.evaluation;return title('INTELLIGENCE / TRANSPARENCY','Evidence behind every score.','A small, reproducible model you can inspect, retrain, and explain.',`<a class="btn" href="model.json" download>↓ Model weights</a><a class="btn primary" href="forgesight-source.zip" download>↓ Complete source</a>`)+`<div class="notice"><span>◈</span><span><strong>Synthetic-data benchmark only.</strong> Held-out windows use a different random seed, but the same simulator. These results do not establish real-world performance.</span></div><section class="panel"><div class="panel-head"><div><h2>From telemetry to production decisions</h2><p>The application performs machine learning and scheduling locally.</p></div><span class="chip">NO LLM REQUIRED</span></div><div class="model-flow"><div class="flow-block"><span>01 / OBSERVE</span><b>30-sample sensor window</b><p>Temperature, vibration, motor current, and extrusion flow. Synthetic streams or imported CSV.</p></div><div class="flow-block"><span>02 / CLASSIFY</span><b>Learned signal patterns</b><p>Six normalized features → trained multinomial logistic classifier → four class scores.</p></div><div class="flow-block"><span>03 / PLAN</span><b>Deadline-aware local search</b><p>Material-compatible dispatch + assignment and sequence search, retaining the better baseline.</p></div></div><div class="stat-grid"><div>Training windows<b>${e.trainWindows.toLocaleString()}</b>Seed ${e.trainSeed} · 900 per class</div><div>Held-out synthetic accuracy<b>${(e.accuracy*100).toFixed(2)}%</b>${e.testWindows.toLocaleString()} windows · seed ${e.testSeed}</div><div>Held-out macro F1<b>${e.macroF1.toFixed(3)}</b>Same simulator · four balanced classes</div></div></section><div class="two-col"><section class="panel prose"><h2>What the model actually learns</h2><p>A <strong>multinomial logistic regression</strong> is fitted in Python using scikit-learn. Learned coefficients and feature scaling are exported to JSON; browser JavaScript runs the same softmax inference.</p><ol><li>Temperature standard deviation</li><li>Temperature slope per sample</li><li>Mean motor current</li><li>Mean vibration</li><li>Mean extrusion flow</li><li>Extrusion slope per sample</li></ol><p><strong>Anomaly score = 1 − P(normal) under this model.</strong> It measures resemblance to simulated fault classes. It is not an estimate of failure timing, remaining life, or physical failure probability.</p><p>Signal contributions compare the selected class logit with the normal-class logit. The displayed σ values are standardized deviations from simulated healthy training windows.</p><h3>Limitations that matter</h3><p>The synthetic generator encodes recognizable faults. Test windows come from that same generator, so good test scores are expected and may not transfer to actual machines. Machine-specific operating baselines, sensor drift, mixed faults, and real-world calibration require further data.</p></section><section class="panel"><div class="panel-head"><div><h2>Held-out confusion matrix</h2><p>Rows: true label · columns: predicted label</p></div></div><div class="table-wrap"><table><thead><tr><th>True / predicted</th><th>Normal</th><th>Blockage</th><th>Thermal</th><th>Vibration</th></tr></thead><tbody>${e.confusion.map((r,i)=>`<tr><td>${['Normal','Blockage','Thermal','Vibration'][i]}</td>${r.map((n,j)=>`<td style="${i===j?'background:#edf3e7;color:#597b42;font-weight:700':''}">${n}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="prose">Four classes × 300 independently generated test windows. Fault severity varies from 0.2 to 1.0.</p><h3 style="margin-top:24px">Business-cost calculation</h3><div class="code">interruption minutes = anomaly score × disruption assumption\nfinish = prior finish + job duration / speed + interruption\nlate cost = max(0, finish − deadline) / 60 × late penalty\nwaste proxy = anomaly score × (material cost + duration / 60 × machine rate)\nobjective = sum(late cost + waste proxy)</div><p class="prose">The scheduler does not solve a global optimum and does not move work already printing. It replans only the future queue, subject to machine availability and material compatibility. Current job availability is fixed; the streaming controls regenerate observation windows and do not simulate completion of the whole factory.</p></section></div><section class="panel prose"><h2>Bring your own telemetry</h2><p>Import a CSV with <strong>12 or more equally spaced numeric samples per machine</strong>. The latest 30 samples are used. Timestamps are seconds; the trained slope features assume a 10-second cadence. Other intervals and operating conditions are outside the training distribution. Supported IDs are P01–P06. Imported streams stay frozen; unmatched machines keep their simulated windows. Your file stays in the browser.</p><div class="code">machine_id,timestamp,temp_c,vibration_mm_s,motor_a,extrusion_mm_s\nP01,0,210.2,1.12,1.35,4.40\nP01,10,210.7,1.18,1.32,4.36</div><div class="download-row"><button class="btn" data-action="sample">↓ Example CSV</button><button class="btn primary" data-action="import">↑ Import telemetry</button><button class="btn" data-action="reset">Reset simulation</button></div></section>`;}
function guideView(){return title('FORGEHACKS / DEMO KIT','You can explain this.','A working project, a simple walkthrough, and the materials to submit it.',`<a class="btn primary" href="forgesight-source.zip" download>↓ Download project</a>`)+`<section class="panel prose"><h2>What you built, in plain English</h2><p>ForgeSight is a manufacturing decision-support prototype for small 3D-print farms. It watches machine readings, recognizes patterns similar to simulated faults, and compares job schedules to reduce a calculated cost of delays and wasted work.</p><p><strong>One sentence for judges:</strong> “ForgeSight turns machine telemetry into an explainable anomaly score, then uses that score to make better production scheduling decisions.”</p><p>AI has two different roles here: ChatGPT assisted with development; a separately trained logistic classifier runs inside the actual product. Describe your role accurately and be ready to walk through the model and cost assumptions.</p><div class="download-row"><button class="btn primary" id="launch-auto-demo">▶ Start automatic demo · 3 min</button><button class="btn" id="launch-guide">Quick manual tour</button><a class="btn" href="submission.md" download>↓ Devpost description & script</a><a class="btn" href="README.md" download>↓ Technical README</a></div></section><section class="panel prose"><h2>Record the automatic demo</h2><p>Start a screen recording, then press <strong>Start demo</strong>. A 3-second countdown leads into a complete 3-minute motion sequence. The demo introduces the problem, displays actual model inference, injects a fault, animates the computed schedule changes, and explains the synthetic benchmark.</p><p>Use fullscreen at 100% browser zoom for the cleanest recording. On-screen text supplies the narration; audio is not generated. Leave the tab visible. You can pause with Space, move between chapters with the arrow keys, replay, or exit with Escape.</p><p>The demo uses its own deterministic sandbox so every replay is reproducible. When it finishes, stop recording and upload the video. For a GitHub copy, the included Pages workflow hosts this same Start demo button once GitHub Pages is enabled.</p></section><div class="two-col"><section class="panel prose"><h2>Optional spoken recording script</h2><h3>0:00–0:25 / The problem</h3><p>“A small print farm needs to decide which machine gets the next job. A late order or a bad print costs time and material. ForgeSight connects machine signals to those business decisions.”</p><h3>0:25–0:55 / Show the data</h3><p>Open Factory overview. Hold telemetry for stable recording. Select P03 and inject an extrusion blockage. “These are generated sensor readings. Watch motor current rise and extrusion flow fall. A trained model recognizes the pattern, and you can inspect the evidence.”</p><h3>0:55–1:35 / Make a decision</h3><p>Click Optimize production. Read the costs and late-order counts that appear on your screen. “This compares a compatible round-robin baseline with a deadline-aware search. It only changes future orders. I can take the machine offline and recalculate.”</p><h3>1:35–2:15 / Prove the AI</h3><p>Open Model & evidence. “The classifier was trained on 3,600 synthetic windows and tested on 1,200 new windows. The learned weights run directly in your browser. These test scores come from the same simulator; they aren't real-machine reliability results.”</p><h3>2:15–2:40 / The next step</h3><p>“You can upload telemetry with the sample CSV format. The next step is a pilot with real printer sensor data, calibrating the model and comparing recommendations with operator decisions.”</p></section><section class="panel"><h2>Before you submit</h2><div class="checklist">${['Download the complete source ZIP.','Create a public GitHub repository and upload the source contents.','Record the working demo (2–4 minutes) and upload it publicly.','Paste submission.md into Devpost and select AI + Business.','Include the public code and video links; verify judge access to any demo link.','State that training data and performance results are synthetic, and disclose AI-assisted development.','Read the event rules and list every teammate.'].map((t,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checklist[i]?'checked':''}><span>${t}</span></label>`).join('')}</div><p class="prose">The live demo is public at forgesight.stableash8.chatgpt.site. Judges can open it and press Start demo. Upload the extracted source files to GitHub and include both the repository and live-demo links in your submission.</p><h3 style="margin-top:26px">Technical answers you can use</h3><p class="prose"><strong>Is it a chatbot?</strong> No. Classification and scheduling are explicit calculations. Explanations are templates based on the predicted class.<br><br><strong>Does it predict failure time?</strong> No. It detects resemblance to a fault pattern in the observation window.<br><br><strong>Are the savings real?</strong> They are computed scenario estimates from a stated cost model.<br><br><strong>What is the ML?</strong> A trained, four-class logistic regression with six telemetry features.</p></section></div>`;}
function render(){document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===state.view));$('#crumb').textContent={overview:'Factory overview',schedule:'Production planner',model:'Model & evidence',guide:'Demo & submission'}[state.view];$('#app').innerHTML=({overview,schedule,model:modelView,guide:guideView}[state.view]||overview)();bind();}
function invalidate(){state.plan=null;state.applied=null;}
function runOptimize(){state.playing=false;state.plan=optimize(state.queue,state.fleet,state.options);state.applied=null;state.view='schedule';location.hash='schedule';log(`Schedule calculated: ${Number.isFinite(state.plan.cost)?money(state.plan.cost)+' scenario cost': 'no compatible allocation'}.`);render();toast(state.plan.unassigned?'No compatible allocation. Restore a PETG machine.':'Production plan calculated. Compare the baseline and proposed costs.');}
function inject(id,mode,severity=state.severity){state.selected=id;state.mode[id]=mode;state.severity=severity;delete state.imported[id];state.source=Object.keys(state.imported).length?'Imported + synthetic telemetry':'Synthetic telemetry';invalidate();updateTelemetry();log(`${id}: ${mode==='normal'?'normal operation restored':mode+' scenario injected'}.`,mode==='normal'?'':'orange');render();toast(`${id}: model recalculated from changed telemetry.`);}
function download(name,content,type='text/plain'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
function sample(){let text='machine_id,timestamp,temp_c,vibration_mm_s,motor_a,extrusion_mm_s\n';for(const m of state.fleet)for(const r of m.rows)text+=`${m.id},${r.timestamp},${r.temp_c.toFixed(3)},${r.vibration_mm_s.toFixed(3)},${r.motor_a.toFixed(3)},${r.extrusion_mm_s.toFixed(3)}\n`;download('forgesight-telemetry.csv',text,'text/csv');toast('CSV downloaded. It contains the current observation windows.');}
function action(a){if(a==='optimize')return runOptimize();if(a==='play'){state.playing=!state.playing;render();return;}if(a==='fault')return inject(state.selected,$('#fault').value,Number($('#severity').value));if(a==='sample')return sample();if(a==='import'){$('#csv-input').click();return;}if(a==='offline'){const m=current();m.offline=!m.offline;invalidate();log(`${m.id} ${m.offline?'excluded from':'restored to'} future dispatch.`,m.offline?'orange':'');render();return;}if(a==='maintain'){const m=current();state.playing=false;m.available+=30;inject(m.id,'normal');log(`${m.id}: simulated service adds 30 minutes to availability.`);render();return;}if(a==='accept'){if(!state.plan||!Number.isFinite(state.plan.cost))return;state.applied=JSON.parse(JSON.stringify(state.plan));log('Proposed future queue accepted in sandbox. No physical commands sent.');render();toast('Plan accepted in this sandbox.');return;}if(a==='report'){download('forgesight-analysis.json',JSON.stringify({generatedAt:new Date().toISOString(),disclaimer:'Synthetic research prototype. Model scores are unvalidated on real machines; costs are scenario proxies.',assumptions:state.options,machines:state.fleet.map(m=>({id:m.id,offline:m.offline,anomalyScore:m.concern,pattern:m.result.label})),baseline:original(),proposed:state.plan,accepted:state.applied},null,2),'application/json');return;}if(a==='reset'){state.fleet=machines();state.mode=Object.fromEntries(state.fleet.map(m=>[m.id,'normal']));state.imported={};state.source='Synthetic telemetry';state.playing=true;state.severity=.8;invalidate();updateTelemetry();log('Factory simulation reset.');render();toast('Simulation reset.');}}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-machine]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.machine;render();});document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{state.checklist[b.dataset.check]=b.checked;});['downtime','lateRate','machineRate'].forEach(k=>{if($('#'+k))$('#'+k).onchange=e=>{const value=Number(e.target.value);if(!Number.isFinite(value)||value<0||!e.target.validity.valid){toast('Use a value in the displayed range.');render();return;}state.options[k]=value;state.applied=null;if(state.plan)state.plan=optimize(state.queue,state.fleet,state.options);render();};});if($('#launch-guide'))$('#launch-guide').onclick=()=>$('#walkthrough').showModal();if($('#launch-auto-demo'))$('#launch-auto-demo').onclick=()=>autoDemo.start();}
$('#csv-input').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error('Use a CSV smaller than 5 MB.');const grouped=parseCSV(await f.text());state.imported={...state.imported,...grouped};state.source='Imported + synthetic telemetry';state.playing=false;invalidate();updateTelemetry();log(`Imported ${Object.keys(grouped).length} telemetry windows. Analysis stays in browser.`);state.selected=Object.keys(grouped)[0];state.view='overview';location.hash='overview';render();toast('CSV imported. Readings are frozen; reset to return to simulation.');}catch(e){toast(e.message);}finally{$('#csv-input').value='';}};
$('#guide-btn').onclick=()=>autoDemo.start();$('#manual-guide-btn').onclick=()=>$('#walkthrough').showModal();$('#walkthrough .close').onclick=()=>$('#walkthrough').close();$('#walkthrough').addEventListener('click',e=>{if(e.target===$('#walkthrough')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#demo-fault').onclick=()=>{state.playing=false;state.view='overview';location.hash='overview';inject('P03','blockage',.8);$('#walkthrough').close();};$('#demo-plan').onclick=()=>{if(state.mode.P03==='normal')inject('P03','blockage',.8);runOptimize();$('#walkthrough').close();};$('#demo-model').onclick=()=>{location.hash='model';$('#walkthrough').close();};$('#full-guide').onclick=()=>$('#walkthrough').close();
function route(){const v=location.hash.slice(1);state.view=['overview','schedule','model','guide'].includes(v)?v:'overview';render();window.scrollTo({top:0,behavior:'instant'});}window.addEventListener('hashchange',route);route();
setInterval(()=>{if(!state.playing||state.view!=='overview'||document.hidden||document.activeElement?.tagName==='SELECT')return;updateTelemetry();invalidate();render();},5000);
